</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#define FORI(i,a,b) for(int i=a;i<=b;i++)
#define FORD(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAXN=262144;

int L,n,k,Mo,len,bit[20],fac[MAXN],inv[MAXN],cnt[MAXN],g[20][MAXN],f[20][MAXN];

int qpow(int base,int exp) {
	int res=1;
	while (exp>0) {
		if (exp&1) res=(ll)res*base%Mo;
		base=(ll)base*base%Mo;
		exp>>=1;
	}
	return res;
}

void add_mod(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub_mod(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void FWT_transform(int *a,int length) {
	for(int size=1;size<length;size<<=1) {
		for(int start=0;start<length;start+=size<<1) {
			for(int offset=0;offset<size;offset++) {
				add_mod(a[start+offset+size],a[start+offset]);
			}
		}
	}
}
void IFWT_transform(int *a,int length) {
	for(int size=1;size<length;size<<=1) {
		for(int start=0;start<length;start+=size<<1) {
			for(int offset=0;offset<size;offset++) {
				sub_mod(a[start+offset+size],a[start+offset]);
			}
		}
	}
}

ll h[20],p[20];

void compute_log() {
	p[0]=0;
	FORI(i,1,n) {
		p[i]=h[i]*i;
		FORI(j,1,i-1) p[i]-=p[j]*h[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	FORI(i,0,n) h[i]=(p[i]+Mo)%Mo;
}

void compute_exp() {
	p[0]=1;
	FORI(i,1,n) {
		p[i]=0;
		FORI(j,1,i) {
			p[i]+=h[j]*p[i-j]%Mo*j;
		}
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	FORI(i,0,n) h[i]=p[i];
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=pwr(k,L);
	if (L%2==1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; FORI(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=pwr(fac[L],Mo-2);
	FORD(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	FORI(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	FORI(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	FORI(i,0,len-1) {
		int s=0;
		FORI(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	FORI(i,2,n) inv[i]=(ll)(Mo-Mo/i)*inv[Mo%i]%Mo;
	FORI(i,0,n) FWT_transform(g[i],len);
	FORI(s,0,len-1) {
		FORI(i,0,n) h[i]=g[i][s];
		compute_log();
		FORI(i,0,n) h[i]=h[i]*k;
		compute_exp();
		FORI(i,0,n) f[i][s]=h[i];
	}
	IFWT_transform(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
